@kt.kernel
def k(x=kt.In(8, 32), y=kt.Out(8, 32)):
    for c in kt.par(2, on=kt.vc):
        if x.shape[0] > 4:
            for i in range(2):
                r = c * 4 + i * 2
                kt.store(y[r : r + 2, :], kt.load(x[r : r + 2, :]))
        else:
            kt.store(y[c * 4 : c * 4 + 4, :], kt.load(x[c * 4 : c * 4 + 4, :]))
